/// PEP 503 / PEP 427 style Python package-name normalization: lowercase,
/// then collapse any run of hyphens, dots, or underscores into a single
/// underscore. This makes name-equality comparisons and wheel-filename
/// construction agree that "my-package", "my_package", "my.package", and
/// "My--Package" all refer to the same PyPI distribution -- PEP 503's own
/// canonicalization rule (`re.sub(r"[-_.]+", "-", name).lower()`), joined
/// with `_` to match PEP 427's wheel-filename escaping instead of PEP
/// 503's own `-` (the join character doesn't affect equality comparisons,
/// only which convention a caller building a filename needs).
pub fn normalize_pypi_package_name(name: &str) -> String {
    pypi_name_parts(name).join("_")
}

/// The PEP 503 normalized project name: the same equivalence, joined with
/// hyphens, which is the form PyPI's own URLs use.
pub fn normalize_pypi_project_name(name: &str) -> String {
    pypi_name_parts(name).join("-")
}

/// The name and version of a wheel or sdist filename; an sdist's last `-` splits them, as a version has no hyphen.
pub fn pypi_dist_filename_parts(filename: &str) -> Option<(&str, &str)> {
    if let Some(stem) = filename.strip_suffix(".whl") {
        let mut segments = stem.split('-');
        return Some((segments.next()?, segments.next()?));
    }
    [".tar.gz", ".tar.bz2", ".tar.xz", ".tar.Z", ".zip"]
        .into_iter()
        .find_map(|ext| filename.strip_suffix(ext))
        .and_then(|stem| stem.rsplit_once('-'))
}

pub fn is_pypi_wheel(filename: &str) -> bool {
    filename.ends_with(".whl")
}

pub fn is_pypi_sdist(filename: &str) -> bool {
    filename.ends_with(".tar.gz")
}

/// Whether `filename` is a wheel or sdist of `package_name` at exactly `version`.
pub fn pypi_dist_belongs_to(filename: &str, package_name: &str, version: &Version) -> bool {
    pypi_dist_filename_parts(filename).is_some_and(|(name, candidate)| {
        normalize_pypi_project_name(name) == normalize_pypi_project_name(package_name)
            && Version::parse(candidate, version.grammar())
                .is_ok_and(|candidate| candidate.compare(version) == Ok(std::cmp::Ordering::Equal))
    })
}

fn pypi_name_parts(name: &str) -> Vec<String> {
    name.to_lowercase()
