        }
    }
    Ok(false)
}

fn names_equal(ecosystem: Ecosystem, left: &str, right: &str) -> bool {
    match ecosystem {
        Ecosystem::Pypi => normalize_pypi_project_name(left) == normalize_pypi_project_name(right),
        _ => left == right,
    }
}

